s32 is the only affected case -- the s64 division/modulo handlers do
not use abs().

Fixes: ec0e2da95f72 ("bpf: Support new signed div/mod instructions.")
Acked-by: Yonghong Song <yonghong.song@linux.dev>
Acked-by: Mykyta Yatsenko <yatsenko@meta.com>
Signed-off-by: Jenny Guanni Qu <qguanni@gmail.com>
Link: https://lore.kernel.org/r/20260311011116.2108005-2-qguanni@gmail.com
Signed-off-by: Alexei Starovoitov <ast@kernel.org>

Here is the root cause:
The use of the kernel's abs() macro on s32 operands in the BPF interpreter's signed division and modulo handlers causes undefined behavior when the operand is S32_MIN (0x80000000), leading to incorrect results and a verifier/interpreter mismatch that can be exploited for out-of-bounds map value access.

Here is the patch:
+/* Absolute value of s32 without undefined behavior for S32_MIN */
+static u32 abs_s32(s32 x)
+{
+	return x >= 0 ? (u32)x : -(u32)x;
+}
+
 /**
  *	___bpf_prog_run - run eBPF program on a given context
  */
 static u64 ___bpf_prog_run(u64 *regs, const struct bpf_insn *insn)
 {
 #define BPF_INSN_2_LBL(x, y)    [BPF_##x | BPF_##y] = &&x##_##y
 #define BPF_INSN_3_LBL(x, y, z) [BPF_##x | BPF_##y | BPF_##z] = &&x##_##y##_##z
 	static const void * const jumptable[256] __annotate_jump_table = {
 		[0 ... 255] = &&default_label,
 		/* Now overwrite non-defaults ... */
 		BPF_INSN_MAP(BPF_INSN_2_LBL, BPF_INSN_3_LBL),
 		/* Non-UAPI available opcodes. */
 		[BPF_JMP | BPF_CALL_ARGS] = &&JMP_CALL_ARGS,
 		[BPF_JMP | BPF_TAIL_CALL] = &&JMP_TAIL_CALL,
 		[BPF_ST  | BPF_NOSPEC] = &&ST_NOSPEC,
 		[BPF_LDX | BPF_PROBE_MEM | BPF_B] = &&LDX_PROBE_MEM_B,
 		[BPF_LDX | BPF_PROBE_MEM | BPF_H] = &&LDX_PROBE_MEM_H,
 		[BPF_LDX | BPF_PROBE_MEM | BPF_W] = &&LDX_PROBE_MEM_W,
 		[BPF_LDX | BPF_PROBE_MEM | BPF_DW] = &&LDX_PROBE_MEM_DW,
 		[BPF_LDX | BPF_PROBE_MEMSX | BPF_B] = &&LDX_PROBE_MEMSX_B,
 		[BPF_LDX | BPF_PROBE_MEMSX | BPF_H] = &&LDX_PROBE_MEMSX_H,
 		[BPF_LDX | BPF_PROBE_MEMSX | BPF_W] = &&LDX_PROBE_MEMSX_W,
 	};
 #undef BPF_INSN_3_LBL
 #undef BPF_INSN_2_LBL
 	u32 tail_call_cnt = 0;

 #define CONT	 ({ insn++; goto select_insn; })
 #define CONT_JMP ({ insn++; goto select_insn; })

 select_insn:
 	goto *jumptable[insn->code];

 	/* Explicitly mask the register-based shift amounts with 63 or 31
 	 * to avoid undefined behavior. Normally this won't affect the
 	 * generated code, for example, in case of native 64 bit archs such
 	 * as x86-64 or arm64, the compiler is optimizing the AND away for
 	 * the interpreter. In case of JITs, each of the JIT backends compiles
 	 * the BPF shift operations to machine instructions which produce
 	 * implementation-defined results in such a case; the resulting
 	 * contents of the register may be arbitrary, but program behaviour
 	 * as a whole remains defined. In other words, in case of JIT backends,
 	 * the AND must /not/ be added to the emitted LSH/RSH/ARSH translation.
 	 */
 	/* ALU (shifts) */
 #define SHT(OPCODE, OP)					\
 	ALU64_##OPCODE##_X:				\
 		DST = DST OP (SRC & 63);		\
 		CONT;					\
 	ALU_##OPCODE##_X:				\
 		DST = (u32) DST OP ((u32) SRC & 31);	\
 		CONT;					\
 	ALU64_##OPCODE##_K:				\
 		DST = DST OP IMM;			\
 		CONT;					\
 	ALU_##OPCODE##_K:				\
 		DST = (u32) DST OP (u32) IMM;		\
 		CONT;
 	/* ALU (rest) */
 #define ALU(OPCODE, OP)					\
 	ALU64_##OPCODE##_X:				\
 		DST = DST OP SRC;			\
 		CONT;					\
 	ALU_##OPCODE##_X:				\
 		DST = (u32) DST OP (u32) SRC;		\
 		CONT;					\
 	ALU64_##OPCODE##_K:				\
 		DST = DST OP IMM;			\
 		CONT;					\
 	ALU_##OPCODE##_K:				\
 		DST = (u32) DST OP (u32) IMM;		\
 		CONT;
 	ALU(ADD,  +)
 	ALU(SUB,  -)
 	ALU(AND,  &)
 	ALU(OR,   |)
 	ALU(XOR,  ^)
 	ALU(MUL,  *)
 	SHT(LSH, <<)
 	SHT(RSH, >>)
 #undef SHT
 #undef ALU
 	ALU_NEG:
 		DST = (u32) -DST;
 		CONT;
 	ALU64_NEG:
 		DST = -DST;
 		CONT;
 	ALU_MOV_X:
 		switch (OFF) {
 		case 0:
 			DST = (u32) SRC;
 			break;
 		case 8:
 			DST = (u32)(s8) SRC;
 			break;
 		case 16:
 			DST = (u32)(s16) SRC;
 			break;
 		}
 		CONT;
 	ALU_MOV_K:
 		DST = (u32) IMM;
 		CONT;
 	ALU64_MOV_X:
 		switch (OFF) {
 		case 0:
 			DST = SRC;
 			break;
 		case 8:
 			DST = (s8) SRC;
 			break;
 		case 16:
 			DST = (s16) SRC;
 			break;
 		case 32:
 			DST = (s32) SRC;
 			break;
 		}
 		CONT;
 	ALU64_MOV_K:
 		DST = IMM;
 		CONT;
 	LD_IMM_DW:
 		DST = (u64) (u32) insn[0].imm | ((u64) (u32) insn[1].imm) << 32;
 		insn++;
 		CONT;
 	ALU_ARSH_X:
 		DST = (u64) (u32) (((s32) DST) >> (SRC & 31));
 		CONT;
 	ALU_ARSH_K:
 		DST = (u64) (u32) (((s32) DST) >> IMM);
 		CONT;
 	ALU64_ARSH_X:
 		(*(s64 *) &DST) >>= (SRC & 63);
 		CONT;
 	ALU64_ARSH_K:
 		(*(s64 *) &DST) >>= IMM;
 		CONT;
 	ALU64_MOD_X:
 		switch (OFF) {
 		case 0:
 			div64_u64_rem(DST, SRC, &AX);
 			DST = AX;
 			break;
 		case 1:
 			AX = div64_s64(DST, SRC);
 			DST = DST - AX * SRC;
 			break;
 		}
 		CONT;
 	ALU_MOD_X:
 		switch (OFF) {
 		case 0:
 			AX = (u32) DST;
 			DST = do_div(AX, (u32) SRC);
 			break;
 		case 1:
-			AX = abs((s32)DST);
-			AX = do_div(AX, abs((s32)SRC));
+			AX = abs_s32((s32)DST);
+			AX = do_div(AX, abs_s32((s32)SRC));
 			if ((s32)DST < 0)
 				DST = (u32)-AX;
 			else
 				DST = (u32)AX;
 			break;
 		}
 		CONT;
 			break;
 		case 1:
-			AX = abs((s32)DST);
-			AX = do_div(AX, abs((s32)IMM));
+			AX = abs_s32((s32)DST);
+			AX = do_div(AX, abs_s32((s32)IMM));
 			if ((s32)DST < 0)
 				DST = (u32)-AX;
 			break;
 		case 1:
-			AX = abs((s32)DST);
-			do_div(AX, abs((s32)SRC));
+			AX = abs_s32((s32)DST);
+			do_div(AX, abs_s32((s32)SRC));
 			if (((s32)DST < 0) == ((s32)SRC < 0))
 				DST = (u32)AX;
 			break;
 		case 1:
-			AX = abs((s32)DST);
-			do_div(AX, abs((s32)IMM));
+			AX = abs_s32((s32)DST);
+			do_div(AX, abs_s32((s32)IMM));
 			if (((s32)DST < 0) == ((s32)IMM < 0))
 				DST = (u32)AX;


